using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ArchitectureApply {
static string R=>Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/Architecture_Rebuild_20261103"));
static string Root="Assets/Afrer_Seconds/05.Model/Environment/Architecture_Rebuilt";
static Bounds B(GameObject g){var rs=g.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
static Material Mat(string name){string path=Root+"/Materials/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}Color col=name=="AS_Concrete"?new Color(.51f,.52f,.50f):name=="AS_PaintedSteel"?new Color(.52f,.55f,.55f):name=="AS_Seal"?new Color(.065f,.078f,.08f):name=="AS_Fastener"?new Color(.33f,.36f,.37f):name=="AS_SafetyYellow"?new Color(.62f,.49f,.17f):new Color(.42f,.60f,.64f,.16f);mat.SetColor("_BaseColor",col);mat.SetFloat("_Metallic",name=="AS_Fastener"?.75f:name=="AS_PaintedSteel"?.4f:0);mat.SetFloat("_Smoothness",name=="AS_Glass"?.7f:name=="AS_Fastener"?.4f:.18f);mat.enableInstancing=true;
if(name=="AS_Glass"){mat.SetFloat("_Surface",1);mat.SetFloat("_Blend",0);mat.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);mat.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);mat.SetFloat("_ZWrite",0);mat.SetOverrideTag("RenderType","Transparent");mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.DisableKeyword("_ALPHATEST_ON");mat.DisableKeyword("_ALPHAPREMULTIPLY_ON");mat.renderQueue=(int)RenderQueue.Transparent;}else{mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Textures/Fine_WornSurface.png"));}EditorUtility.SetDirty(mat);return mat;}
static void Preview(GameObject prefab,string file){var p=new PreviewRenderUtility();var g=UnityEngine.Object.Instantiate(prefab);p.AddSingleGO(g);var b=B(g);float s=b.size.magnitude;p.camera.transform.position=b.center+new Vector3(-.9f,.55f,-1.6f)*s;p.camera.transform.LookAt(b.center);p.camera.fieldOfView=35;p.camera.nearClipPlane=.001f;p.camera.farClipPlane=100;p.camera.clearFlags=CameraClearFlags.Color;p.camera.backgroundColor=new Color(.16f,.17f,.19f);p.lights[0].intensity=1.5f;p.lights[0].transform.rotation=Quaternion.Euler(40,40,0);p.lights[1].intensity=1;p.lights[1].transform.rotation=Quaternion.Euler(340,210,0);p.ambientColor=new Color(.3f,.3f,.3f);for(int i=0;i<3;i++){p.BeginStaticPreview(new Rect(0,0,800,800));p.Render(true);var t=p.EndStaticPreview();if(i==2)File.WriteAllBytes(file,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}p.Cleanup();}
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);Directory.CreateDirectory(R+"/PrefabBackup");Directory.CreateDirectory(Root+"/Materials");AssetDatabase.Refresh();var texture=(TextureImporter)AssetImporter.GetAtPath(Root+"/Textures/Fine_WornSurface.png");texture.wrapMode=TextureWrapMode.Repeat;texture.sRGBTexture=true;texture.maxTextureSize=1024;texture.mipmapEnabled=true;texture.SaveAndReimport();var names=new[]{"AS_Concrete","AS_PaintedSteel","AS_Seal","AS_Fastener","AS_SafetyYellow","AS_Glass"};var mats=names.ToDictionary(n=>n,n=>Mat(n));var cfg=JArray.Parse(File.ReadAllText(R+"/rebuild_manifest.json"));var facts=new List<object>();
foreach(JObject a in cfg){string name=(string)a["name"],path=(string)a["prefabPath"],model=(string)a["modelPath"];var imp=(ModelImporter)AssetImporter.GetAtPath(model);imp.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;imp.materialLocation=ModelImporterMaterialLocation.InPrefab;imp.importAnimation=false;imp.importCameras=false;imp.importLights=false;imp.importNormals=ModelImporterNormals.Import;imp.importTangents=ModelImporterTangents.CalculateMikk;imp.meshCompression=ModelImporterMeshCompression.Off;imp.addCollider=false;imp.SaveAndReimport();if(!File.Exists(R+"/PrefabBackup/"+name+".prefab")){File.Copy(path,R+"/PrefabBackup/"+name+".prefab");File.Copy(path+".meta",R+"/PrefabBackup/"+name+".prefab.meta");Preview(AssetDatabase.LoadAssetAtPath<GameObject>(path),R+"/"+name+"_before.png");}
var content=PrefabUtility.LoadPrefabContents(path);var existing=content.transform.Find("RebuiltArchitectureVisual");if(existing)UnityEngine.Object.DestroyImmediate(existing.gameObject);foreach(var old in content.GetComponentsInChildren<Renderer>()){old.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(old);}var go=new GameObject("RebuiltArchitectureVisual");go.transform.SetParent(content.transform,false);var modelGo=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(model));modelGo.transform.SetParent(go.transform,false);var b=B(go);var size=new Vector3((float)a["sizeUnity"][0],(float)a["sizeUnity"][1],(float)a["sizeUnity"][2]);go.transform.localScale=new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z);b=B(go);go.transform.localPosition+=new Vector3(0,size.y*.5f,0)-b.center;
foreach(var renderer in go.GetComponentsInChildren<Renderer>()){renderer.sharedMaterials=renderer.sharedMaterials.Select(m=>{string key=names.FirstOrDefault(n=>m!=null&&m.name.StartsWith(n));if(key==null)throw new Exception("Unknown material "+(m?m.name:"null"));return mats[key];}).ToArray();renderer.shadowCastingMode=renderer.sharedMaterials.Any(m=>m.name=="AS_Glass")?ShadowCastingMode.Off:ShadowCastingMode.On;renderer.receiveShadows=true;PrefabUtility.RecordPrefabInstancePropertyModifications(renderer);}
foreach(var t in go.GetComponentsInChildren<Transform>())GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.BatchingStatic|StaticEditorFlags.ReflectionProbeStatic);if(go.GetComponentsInChildren<Collider>().Length>0)throw new Exception("Unexpected Collider");b=B(content);if((b.size-size).magnitude>.001f)throw new Exception("Module size mismatch "+name+" actual="+b.size+" target="+size);PrefabUtility.SaveAsPrefabAsset(content,path);PrefabUtility.UnloadPrefabContents(content);Preview(AssetDatabase.LoadAssetAtPath<GameObject>(path),R+"/"+name+"_after.png");facts.Add(new{name=name,prefabPath=path,size=new[]{b.size.x,b.size.y,b.size.z},center=new[]{b.center.x,b.center.y,b.center.z},sourceModel=model,materials=names,collidersAdded=0});}
AssetDatabase.SaveAssets();File.WriteAllText(R+"/unity_import_facts.json",JsonConvert.SerializeObject(facts,Formatting.Indented));return "6 rebuilt architecture models imported and connected to existing prefabs";}}

